import { apiGetHelper } from '../commonUtills/helperAxios';

const API_URL = process.env.REACT_APP_SCHOOL_BACKEND_URL;

const fetchTimetableData = async (path, params) => {
  const response = await apiGetHelper(`${API_URL}/miscellaneous/${path}`, {
    headers: { 'Content-Type': 'application/json' },
    params,
  });
  return response.data;
};

export const fetchStaffDailyTimetable = (params) =>
  fetchTimetableData('fetch-staff-daily-timetable', params);

export const fetchStaffPeriodTopicDetails = (params) =>
  fetchTimetableData('fetch-staff-period-topic-details', params);
